import re
import datetime
import json

def extract(text: str) -> dict:
    t = text.strip().lower()
    if not t:
        raise ValueError('not appointments')

    appt_words = r'(?:appointment|appointments|meeting|meetings|event|events|visit|visits|schedule|scheduled|booking|bookings|calendar)' 
    ask_words = r'(?:any|do|what|which|show|list|find|see|upcoming|upcoming\s+' + appt_words + r'|' + appt_words + r'\s+.*(?:have|are|is|should\s+be\s+aware\s+of)?)'

    if not re.search(appt_words, t, re.I):
        raise ValueError('not appointments')

    negative = [
        r'\b(cancel|reschedule|book|create|make|schedule)\b',
        r'\b(reminder|reminders)\b',
        r'\b(call|calls|email|emails|message|messages|task|tasks|todo)\b'
    ]
    for pat in negative:
        if re.search(pat, t, re.I):
            raise ValueError('not appointments')

    if not re.search(r'\b(any|what|which|show|list|find|see|do|are|is|upcoming)\b', t, re.I) and not re.search(r'\bshould be aware of\b', t, re.I):
        raise ValueError('not appointments')

    def norm_space(s: str) -> str:
        return re.sub(r'\s+', ' ', s.strip().lower())

    month = r'(?:january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)'
    iso = r'\d{4}-\d{2}-\d{2}'
    day_month = rf'(?:\d{{1,2}}(?:st|nd|rd|th)?\s+{month}(?:\s+\d{{4}})?|{month}\s+\d{{1,2}}(?:st|nd|rd|th)?(?:,?\s*\d{{4}})?|{month}(?:\s+\d{{4}})?)'
    date_phrase = rf'(?:{iso}|{day_month})'

    m = re.search(rf'\bbetween\s+({date_phrase})\s+and\s+({date_phrase})\b', t, re.I)
    if m:
        return {"intent": "appointments", "period": "range", "start": norm_space(m.group(1)), "end": norm_space(m.group(2))}

    m = re.search(rf'\bfrom\s+({date_phrase})\s+to\s+({date_phrase})\b', t, re.I)
    if m:
        return {"intent": "appointments", "period": "range", "start": norm_space(m.group(1)), "end": norm_space(m.group(2))}

    m = re.search(rf'\bsince\s+({date_phrase})\b', t, re.I)
    if m:
        return {"intent": "appointments", "period": "range", "start": norm_space(m.group(1))}

    m = re.search(rf'\bin\s+({month}(?:\s+\d{{4}})?)\b', t, re.I)
    if m:
        v = norm_space(m.group(1))
        return {"intent": "appointments", "period": "range", "start": v, "end": v}

    mappings = [
        (r'\bthis\s+month\b', 'this_month'),
        (r'\bthis\s+week\b', 'this_week'),
        (r'\bnext\s+month\b', 'next_month'),
        (r'\b(next\s+7\s+days|next\s+week)\b', 'next_7_days'),
        (r'\b(next\s+14\s+days|next\s+two\s+weeks|next\s+2\s+weeks|two\s+weeks|14\s+days)\b', 'next_14_days'),
        (r'\b(next\s+30\s+days|30\s+days)\b', 'next_30_days'),
        (r'\b(last\s+month|past\s+30\s+days|last\s+30\s+days)\b', 'last_30_days'),
        (r'\ball\b', 'all')
    ]
    for pat, val in mappings:
        if re.search(pat, t, re.I):
            return {"intent": "appointments", "period": val}

    return {"intent": "appointments", "period": "upcoming"}
